-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 14: Modelagem semântica — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('7addf850-bdda-56ae-b825-81089b3f090d', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Qual é uma finalidade da modelagem semântica?', '["Substituir toda análise de requisitos.","Eliminar o significado dos dados.","Representar conceitos do domínio e suas regras de forma estruturada.","Escolher exclusivamente o tamanho de páginas.","Determinar senhas de rede."]'::jsonb, 2, 'Entidades, propriedades e relacionamentos ajudam a explicitar a semântica do domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.2, páginas 676–679 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1fdf2f76-9b4f-592b-9840-602b40ce3c26', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Fácil', 'Um equipamento individual distinguível no domínio é exemplo de:', '["Operador de agregação.","Entidade.","Arquivo de log.","Regra de bloqueio.","Índice obrigatório."]'::jsonb, 1, 'Uma entidade corresponde a um objeto distinguível de interesse para a organização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('90463aa6-1766-527d-b1c1-4b694eb50862', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'A data de aquisição de um equipamento é, no modelo E/R, uma:', '["Superclasse necessariamente.","Junção física.","Propriedade da entidade.","Entidade fraca obrigatória.","Transação distribuída."]'::jsonb, 2, 'Propriedades descrevem aspectos das entidades ou dos relacionamentos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7046663c-3050-5517-b755-949f3c0138fd', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'A associação entre técnicos e equipamentos que inspecionam é um:', '["Checkpoint.","Operador de criptografia.","Relacionamento.","Tipo físico de disco.","Catálogo de usuários."]'::jsonb, 2, 'Relacionamentos representam associações entre entidades do domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6559630e-c4a7-5298-8f0f-2c93582bcb13', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Uma entidade cuja existência depende de outra é denominada, na terminologia discutida:', '["Fraca.","Independente obrigatoriamente.","Materializada.","Primária por definição.","Irredutível."]'::jsonb, 0, 'O capítulo associa entidades fracas à dependência de existência em relação a outra entidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0139f77b-e899-5bae-a5eb-973990409581', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Um técnico inspeciona vários equipamentos e um equipamento recebe vários técnicos. A cardinalidade é:', '["Muitos para um apenas do técnico para o equipamento.","Um para um.","Muitos para muitos.","Zero para um obrigatoriamente.","Um para muitos apenas do técnico para o equipamento."]'::jsonb, 2, 'Ambos os lados podem participar em várias ocorrências da associação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c62de188-d2b2-558d-b12a-4f052535997c', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Cada empregado pertence a um departamento, e cada departamento possui vários empregados. Do departamento para empregados, há:', '["Nenhum relacionamento.","Muitos para muitos obrigatoriamente.","Muitos para um.","Um para um.","Um para muitos."]'::jsonb, 4, 'A cardinalidade precisa ser lida no sentido indicado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5f64e312-4616-59e1-823d-cb2c3de5ba6a', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Uma propriedade calculada a partir de outras, como total de itens, é:', '["Uma entidade regular.","Derivada.","Sempre multivalorada.","Obrigatoriamente identificadora.","Um índice interno."]'::jsonb, 1, 'A propriedade derivada possui regra de cálculo a partir de informações disponíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4e9c78a9-4312-5220-989b-e4cf189099cc', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Fácil', 'Vários telefones para a mesma pessoa exemplificam uma propriedade:', '["Sem relação com a entidade.","Obrigatoriamente sem domínio.","Sempre identificadora.","Multivalorada no modelo conceitual.","Sempre derivada."]'::jsonb, 3, 'A representação lógica posterior precisa expressar adequadamente essa multiplicidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cd438dfc-edac-5876-89b4-375612b41dd0', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Rua, número e cidade agrupados em endereço ilustram uma propriedade:', '["Obrigatoriamente fraca.","Um relacionamento ternário necessariamente.","Uma chave estrangeira por definição.","Composta.","Sem componentes."]'::jsonb, 3, 'Uma propriedade composta pode ser descrita em termos de componentes menores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e30c18a-244f-5d5e-9b1b-a9bb12d68fc7', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Um diagrama E/R dispensa a especificação complementar de todas as regras de integridade?', '["Não, porque diagramas não representam entidades.","Sim, desde que não existam atributos.","Sim, se houver retângulos.","Sim, todo desenho formaliza qualquer regra.","Não; regras podem não estar expressas pela notação gráfica utilizada."]'::jsonb, 4, 'O capítulo alerta para a imprecisão e as lacunas de diagramas na descrição de restrições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.4, páginas 686–688 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ee26e012-b069-5907-b476-1090adc97aa5', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Ao mapear um relacionamento muitos para muitos para o modelo relacional, é comum criar:', '["Uma relvar de associação com referências aos participantes.","Um índice sem dados.","Uma cópia de segurança por entidade.","Um usuário por ocorrência.","Uma coluna que concatena todos os identificadores."]'::jsonb, 0, 'A associação é representada por fatos próprios ligados às entidades participantes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ada556ff-2ed6-5193-85f2-2b35d42789b5', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Qual estrutura representa adequadamente notas de alunos em disciplinas?', '["Apenas uma nota única no cadastro geral da disciplina.","Um nome de aluno dentro da senha do professor.","Uma nota única global para todos os alunos.","Somente um índice na tabela de alunos.","Uma associação AlunoDisciplina com as referências e a nota."]'::jsonb, 4, 'A nota depende da ocorrência da associação, não apenas de um dos participantes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae2d9081-3d41-5d71-94b7-d7cb3a0eac9e', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Para representar cada empregado ligado a um departamento, uma opção usual é:', '["Uma tabela sem identificadores.","Uma chave estrangeira de departamento em empregado.","Uma chave primária igual para todos os empregados.","O endereço físico do departamento na aplicação.","Uma lista de nomes concatenados no departamento."]'::jsonb, 1, 'A chave estrangeira representa a associação muitos para um, respeitadas as demais restrições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('87b6ad8d-a475-5c51-be7d-6814084aed41', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma chave estrangeira, sozinha, garante um relacionamento um para um?', '["Não; a exclusividade do lado referenciador exige restrição adicional apropriada.","Sim, se a coluna for texto.","Sim, toda referência é um para um.","Sim, se o banco tiver índices.","Não, porque chaves estrangeiras não ligam entidades."]'::jsonb, 0, 'Unicidade e obrigatoriedade precisam ser modeladas além da mera referência.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5b2c2ef7-c1ab-5ae5-8bb6-26b53c4b439b', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Um relacionamento que liga empregado a seu supervisor, ambos do tipo empregado, é:', '["Necessariamente muitos para muitos.","Uma propriedade sem entidades.","Impossível no modelo E/R.","Uma herança de tipos obrigatória.","Recursivo, com papéis distintos."]'::jsonb, 4, 'A mesma classe de entidades pode participar com papéis diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e41272b-cbc8-50c0-b685-33acfc374a10', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Substituir um relacionamento ternário por três relacionamentos binários é sempre seguro?', '["Não; pode perder restrições sobre a combinação dos três participantes.","Sim, por identidade matemática universal.","Sim, porque entidades só se ligam aos pares.","Sim, se houver três índices.","Não, porque relacionamentos binários são proibidos."]'::jsonb, 0, 'A associação entre triplas pode conter informação não preservada por pares independentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ec149ec2-afb5-59c6-82ab-1ee6c2e0f8e8', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Uma entidade pode participar de zero ocorrências de um relacionamento quando a participação é:', '["Sempre total.","Identificadora por definição.","Obrigatória.","Opcional.","Fisicamente ordenada."]'::jsonb, 3, 'Participação opcional admite ausência de associação; cardinalidade máxima é outra informação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0cac28be-db7e-5f1b-86fb-d9f8a59ab91c', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Ao transformar conceitos do domínio em objetos formais, é necessário também definir:', '["Um índice por palavra do enunciado.","Somente cores dos diagramas.","A ordem física de todas as tuplas.","Regras de integridade e operações correspondentes.","A senha de cada usuário final."]'::jsonb, 3, 'Símbolos sem regras e operações não fornecem uma descrição formal suficiente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.2, páginas 676–679 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6f7b73a8-0d23-55b7-ac8a-87640e508ae7', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Na análise de Date, usar diagramas E/R obriga a adotar integralmente todas as ideias de um único modelo semântico?', '["Sim, porque qualquer diagrama é um esquema interno.","Não; a técnica de diagramação e o modelo são propostas distinguíveis.","Sim, por definição de diagrama.","Não, porque diagramas nunca têm semântica.","Sim, desde que haja entidades fracas."]'::jsonb, 1, 'O autor distingue a notação gráfica dos compromissos teóricos de um modelo específico.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.6, páginas 696–699 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
